<?php
namespace App\Controllers;use App\Models\Photo;use App\Models\PhotoSet;use App\Core\Database;
final class StoreController{
 public function index():void{$db=Database::db();$cta=$db->query("SELECT * FROM homepage_cta WHERE id=1 AND active=1")->fetch()?:null;$hero=null;try{$hero=$db->query("SELECT * FROM homepage_hero WHERE id=1")->fetch()?:null;}catch(\Throwable $e){}$coverExpr='MIN(p.id)';$previewOrder='p.set_id,p.id';try{$db->query('SELECT cover_photo_id FROM photo_sets LIMIT 0');$coverExpr='COALESCE(MAX(CASE WHEN p.id=ps.cover_photo_id THEN p.id END),MIN(p.id))';$previewOrder='p.set_id,(p.id=ps.cover_photo_id) DESC,p.id';}catch(\Throwable $e){}$saleFilter="(ps.individual_enabled=1 OR ps.set_enabled=1 OR ps.pack_enabled=1)";$events=$db->query("SELECT e.*,COUNT(DISTINCT p.id) photos_count,COUNT(DISTINCT ps.id) sets_count,MIN(p.id) cover_id,MIN(p.preview_path) cover,MIN(ps.set_price) from_set_price FROM events e JOIN photo_sets ps ON ps.event_id=e.id AND ps.status='active' AND $saleFilter JOIN photos p ON p.set_id=ps.id AND p.status='active' WHERE e.status='published' GROUP BY e.id ORDER BY e.event_date DESC LIMIT 3")->fetchAll();$sets=$db->query("SELECT ps.*,e.name event_name,COUNT(p.id) photos_count,$coverExpr cover_id,MIN(p.preview_path) preview_path FROM photo_sets ps JOIN events e ON e.id=ps.event_id JOIN photos p ON p.set_id=ps.id AND p.status='active' WHERE ps.status='active' AND ps.set_enabled=1 AND e.status='published' GROUP BY ps.id ORDER BY ps.id DESC LIMIT 6")->fetchAll();$q=trim($_GET['q']??'');$catalogSql="SELECT ps.*,e.name event_name,COUNT(p.id) photos_count,$coverExpr cover_id,MIN(p.preview_path) preview_path,MIN(p.price) individual_price FROM photo_sets ps JOIN events e ON e.id=ps.event_id JOIN photos p ON p.set_id=ps.id AND p.status='active' WHERE ps.status='active'";$catalogArgs=[];if($q!==''){$catalogSql.=' AND (ps.bib_number LIKE ? OR ps.name LIKE ? OR e.name LIKE ?)';$catalogArgs=["%$q%","%$q%","%$q%"];} $catalogSql.=' GROUP BY ps.id ORDER BY ps.id DESC';$catalogQuery=$db->prepare($catalogSql);$catalogQuery->execute($catalogArgs);$catalogSets=$catalogQuery->fetchAll();$setPreviews=[];$rows=$db->query("SELECT p.id,p.set_id,p.preview_path FROM photos p JOIN photo_sets ps ON ps.id=p.set_id JOIN events e ON e.id=ps.event_id WHERE p.status='active' AND ps.status='active' ORDER BY $previewOrder")->fetchAll();foreach($rows as $row)if(count($setPreviews[$row['set_id']]??[])<4)$setPreviews[$row['set_id']][]=$row;view('store/index',['events'=>$events,'sets'=>$sets,'catalogSets'=>$catalogSets,'setPreviews'=>$setPreviews,'cta'=>$cta,'hero'=>$hero]);}
 public function photo():void{$photo=Photo::find((int)($_GET['id']??0));if(!$photo){http_response_code(404);exit('Foto no encontrada');}$related=$photo['set_id']?PhotoSet::photos((int)$photo['set_id']):[$photo];view('store/photo',['photo'=>$photo,'related'=>$related,'pageTitle'=>'Detalle de fotografía | Ultra','flowPage'=>true,'bodyClass'=>'inner','toplineRight'=>'SELECCIONA TUS FOTOS']);}
 public function faq():void{view('store/faq',['pageTitle'=>'Preguntas frecuentes | Ultra','flowPage'=>true,'bodyClass'=>'inner','faqPage'=>true]);}
}
